import os
from typing import Dict, List, Tuple, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest


def _polygon_center(polygon: Optional[List[float]]) -> Tuple[float, float]:
    if not polygon:
        return (0.0, 0.0)
    xs = polygon[0::2]
    ys = polygon[1::2]
    return (sum(xs) / len(xs), sum(ys) / len(ys))


def _line_center(line) -> Tuple[float, float]:
    return _polygon_center(getattr(line, "polygon", None))


def _field_center(field) -> Tuple[float, float]:
    brs = getattr(field, "bounding_regions", None) or []
    if brs and getattr(brs[0], "polygon", None):
        return _polygon_center(brs[0].polygon)
    return (0.0, 0.0)


def _extract_text_from_field(field) -> str:
    if field is None:
        return ""
    value = getattr(field, "value_string", None)
    if value:
        return str(value)
    content = getattr(field, "content", None)
    if content:
        return str(content)
    value_obj = getattr(field, "value", None)
    if value_obj is not None:
        return str(value_obj)
    return ""


def _nearest_line_text(page, target_center: Tuple[float, float], side: str = "left") -> str:
    best_text = ""
    best_score = float("inf")
    tx, ty = target_center

    for line in getattr(page, "lines", []) or []:
        lx, ly = _line_center(line)
        dx = tx - lx
        dy = abs(ty - ly)

        if side == "left" and dx <= 0:
            continue
        if side == "right" and dx >= 0:
            continue

        score = abs(dx) + (dy * 2.0)
        if score < best_score:
            best_score = score
            best_text = (getattr(line, "content", None) or "").strip()

    return best_text


def extract_key_value_pairs(document_path: str) -> Dict[str, str]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(key),
    )

    with open(document_path, "rb") as f:
        document_bytes = f.read()

    poller = client.begin_analyze_document(
        model_id="prebuilt-document",
        body=AnalyzeDocumentRequest(bytes_source=document_bytes),
        features=["keyValuePairs"],
    )
    result = poller.result()

    extracted: Dict[str, str] = {}

    for kv in getattr(result, "key_value_pairs", []) or []:
        key_text = _extract_text_from_field(getattr(kv, "key", None)).strip()
        value_text = _extract_text_from_field(getattr(kv, "value", None)).strip()
        if key_text:
            extracted[key_text] = value_text

    if extracted:
        return extracted

    pages = getattr(result, "pages", []) or []
    for page in pages:
        page_lines = getattr(page, "lines", []) or []
        for line in page_lines:
            text = (getattr(line, "content", None) or "").strip()
            if ":" in text:
                left, right = text.split(":", 1)
                key = left.strip()
                value = right.strip()
                if key:
                    extracted[key] = value

    if extracted:
        return extracted

    for doc in getattr(result, "documents", []) or []:
        fields = getattr(doc, "fields", None) or {}
        if not fields:
            continue

        page_map = {getattr(p, "page_number", None): p for p in pages}

        for field_name, field_value in fields.items():
            value_text = _extract_text_from_field(field_value).strip()
            if value_text:
                extracted[str(field_name)] = value_text
                continue

            center = _field_center(field_value)
            brs = getattr(field_value, "bounding_regions", None) or []
            page_number = getattr(brs[0], "page_number", None) if brs else None
            page = page_map.get(page_number)

            if page:
                inferred_key = _nearest_line_text(page, center, side="left") or str(field_name)
            else:
                inferred_key = str(field_name)

            extracted[inferred_key] = value_text

    return extracted
